+// Multi-client-isolation MCP server.
+// Each client_id owns an independent key/value map. A value written by one
+// client is never visible to another.
+
+const clients = new Map(); // client_id -> Map(key -> value)
+
+function requireNonEmptyString(value, name) {
+  if (typeof value !== 'string' || value.length === 0) {
+    const err = new Error(`${name} must be a non-empty string`);
+    err.code = -32602;
+    throw err;
+  }
+}
+
+function requireKnownClient(clientId) {
+  if (!clients.has(clientId)) {
+    const err = new Error(`unknown client: ${clientId}`);
+    err.code = -32602;
+    throw err;
+  }
+}
+
+export async function listTools() {
+  return [
+    {
+      name: 'open_client',
+      description: 'Open a client with its own independent key/value map.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          client_id: { type: 'string', description: 'Unique non-empty client identifier.' }
+        },
+        required: ['client_id'],
+        additionalProperties: false
+      }
+    },
+    {
+      name: 'client_put',
+      description: "Write a non-empty key/value pair into the owning client's map.",
+      inputSchema: {
+        type: 'object',
+        properties: {
+          client_id: { type: 'string', description: 'Owning client identifier.' },
+          key: { type: 'string', description: 'Non-empty key.' },
+          value: { type: 'string', description: 'Non-empty value.' }
+        },
+        required: ['client_id', 'key', 'value'],
+        additionalProperties: false
+      }
+    },
+    {
+      name: 'client_get',
+      description: "Read a key from the owning client's map.",
+      inputSchema: {
+        type: 'object',
+        properties: {
+          client_id: { type: 'string', description: 'Owning client identifier.' },
+          key: { type: 'string', description: 'Non-empty key.' }
+        },
+        required: ['client_id', 'key'],
+        additionalProperties: false
+      }
+    }
+  ];
+}
+
+export async function callTool(name, args = {}) {
+  switch (name) {
+    case 'open_client': {
+      requireNonEmptyString(args.client_id, 'client_id');
+      if (!clients.has(args.client_id)) {
+        clients.set(args.client_id, new Map());
+      }
+      return { content: [{ type: 'text', text: `client ${args.client_id} opened` }] };
+    }
+    case 'client_put': {
+      requireNonEmptyString(args.client_id, 'client_id');
+      requireNonEmptyString(args.key, 'key');
+      requireNonEmptyString(args.value, 'value');
+      requireKnownClient(args.client_id);
+      clients.get(args.client_id).set(args.key, args.value);
+      return { content: [{ type: 'text', text: 'ok' }] };
+    }
+    case 'client_get': {
+      requireNonEmptyString(args.client_id, 'client_id');
+      requireNonEmptyString(args.key, 'key');
+      requireKnownClient(args.client_id);
+      const map = clients.get(args.client_id);
+      if (!map.has(args.key)) {
+        const err = new Error(`unknown key: ${args.key}`);
+        err.code = -32602;
+        throw err;
+      }
+      return { content: [{ type: 'text', text: map.get(args.key) }] };
+    }
+    default: {
+      const err = new Error(`unknown tool: ${name}`);
+      err.code = -32601;
+      throw err;
+    }
+  }
+}
